-- Original NumPy 2.5.3 where/select; scalar and layout contracts preserved.
local np=require('luaray_core')
local cases,checks=0,0
local function eq(a,b,label)
 checks=checks+1
 if type(b)=='table' then
  assert(type(a)=='table' and #a==#b,label..': shape')
  for i=1,#b do eq(a[i],b[i],label..'['..i..']') end
 elseif type(b)=='number' and b~=b then assert(a~=a,label..': NaN')
 elseif type(b)=='userdata' then eq(a.real,b.real,label..'.real');eq(a.imag,b.imag,label..'.imag')
 else assert(a==b,label..': '..tostring(a)..' != '..tostring(b)) end
end

do
local function chunk()
-- 1: dtypes/int8/int8/bool/True; source error=None
do
local condition=true
local x=np.array({{0,1,2},{3,4,5}},"int8")
local y=np.array({{10,11,12},{13,14,15}},"int8")
local ok,result=pcall(function() return np.where(condition,x,y) end)
assert(ok==true,"dtypes/int8/int8/bool/True: acceptance"..": "..tostring(result))
assert(type(result)=="userdata","dtypes/int8/int8/bool/True: ndarray result")
eq(result:tolist(),{{0,1,2},{3,4,5}},"dtypes/int8/int8/bool/True: result")
eq(result.shape,{2,3},"dtypes/int8/int8/bool/True: result: shape")
eq(result.strides,{3,1},"dtypes/int8/int8/bool/True: result: strides")
eq(result.dtype,"int8","dtypes/int8/int8/bool/True: result: dtype")
eq(x:tolist(),{{0,1,2},{3,4,5}},"dtypes/int8/int8/bool/True: x state")
eq(x.shape,{2,3},"dtypes/int8/int8/bool/True: x state: shape")
eq(x.strides,{3,1},"dtypes/int8/int8/bool/True: x state: strides")
eq(x.dtype,"int8","dtypes/int8/int8/bool/True: x state: dtype")
eq(y:tolist(),{{10,11,12},{13,14,15}},"dtypes/int8/int8/bool/True: y state")
eq(y.shape,{2,3},"dtypes/int8/int8/bool/True: y state: shape")
eq(y.strides,{3,1},"dtypes/int8/int8/bool/True: y state: strides")
eq(y.dtype,"int8","dtypes/int8/int8/bool/True: y state: dtype")
cases=cases+1
end
